describe('Part 13 repair API exact scoped evidence, disconnected provider',()=>{
 it('rejects client-invented diagnostic and cross-project sources',async()=>{const r=await request('/api/projects/'+proj+'/repair','POST',{instructions:'Fix bug',kind:'build',evidenceId:'invented',text:'pretend compiler error'},alice);expect(r.status).toBe(404);const denied=await request('/api/projects/'+proj+'/repair','GET',undefined,bob);expect([403,404]).toContain(denied.status)});
 it('captures a labeled test-only receipt; never invents a repair while disconnected',async()=>{const current=await request('/api/projects/'+proj+'/agent/context','GET',undefined,alice);const c:any=await current.json();const tj=await request('/api/projects/'+proj+'/terminal','POST',{command:'pwd',baseRevision:c.snapshot.revision,sourceDigest:c.snapshot.sourceDigest},alice);expect(tj.status).toBe(201);const job:any=await tj.json();await request('/api/projects/'+proj+'/terminal/'+job.id+'/events','POST',{runtimeId:job.runtimeId,events:[{seq:1,stream:'stderr',text:'test-only receipt: SyntaxError at index.html:1'}]},alice);await request('/api/projects/'+proj+'/terminal/'+job.id+'/finish','POST',{runtimeId:job.runtimeId,status:'failed',exitCode:1,durationMs:1},alice);const session=await request('/api/projects/'+proj+'/repair','POST',{instructions:'Repair the observed syntax failure',kind:'terminal',evidenceId:job.id},alice);expect(session.status).toBe(201);const s:any=await session.json();expect(s.evidence.trust).toBe('browser-unverified');expect(s.evidence.text).toContain('test-only receipt');const blocked=await request('/api/projects/'+proj+'/repair/'+s.id+'/propose','POST',{},alice);expect(blocked.status).toBe(503);expect((await blocked.json() as any).error).toBe('repair_ai_provider_not_connected');const data:any=await (await request('/api/projects/'+proj+'/repair/'+s.id,'GET',undefined,alice)).json();expect(data.attempts).toBe(0);expect(data.proposal_id).toBeNull();const duplicate=await request('/api/projects/'+proj+'/repair','POST',{instructions:'Fix it',kind:'terminal',evidenceId:job.id},alice);expect(duplicate.status).toBe(409);expect((await request('/api/projects/'+proj+'/repair/'+s.id+'/stop','POST',{},alice)).status).toBe(200);expect((await request('/api/projects/'+proj+'/repair/'+s.id+'/propose','POST',{},alice)).status).toBe(409)});
});

describe('Part 13 server loop with labeled planner injection, not a live model',()=>{
 it('persists review-only patch, requires exact owner approval, then requires a new build',async()=>{const {repairApi}=await import('../src/repair-api');await db.prepare('DELETE FROM rate_limits').run();const item:any=await (await request('/api/workspaces/'+ws+'/projects','POST',{name:'Repair DI QA'},alice)).json();const initial:any=await (await request('/api/projects/'+item.id+'/proposals','POST',{baseRevision:0,bundle:{stack:'static-web-v1',files:{'index.html':'<script src="app.js"></script>','app.js':'const x = ;','keep.txt':'unchanged'},schema:[],permissions:[]}},alice)).json();await request('/api/proposals/'+initial.id+'/approve','POST',{digest:initial.digest},alice);const c:any=await (await request('/api/projects/'+item.id+'/agent/context','GET',undefined,alice)).json();const {build}=await import('../runtime/build');const logs:string[]=[];const fail=await build(c.snapshot.files,x=>logs.push(x));expect(fail.status).toBe('failed');const b:any=await (await request('/api/projects/'+item.id+'/build','POST',{command:'build static-web-v1',baseRevision:1,sourceDigest:c.snapshot.sourceDigest},alice)).json();await request('/api/projects/'+item.id+'/build/'+b.id+'/events','POST',{runtimeId:b.runtimeId,events:logs.map((text,i)=>({seq:i+1,stream:'stderr',text}))},alice);await request('/api/projects/'+item.id+'/build/'+b.id+'/finish','POST',{runtimeId:b.runtimeId,...fail},alice);const session:any=await (await request('/api/projects/'+item.id+'/repair','POST',{instructions:'Fix the syntax failure',kind:'build',evidenceId:b.id},alice)).json();const env={DB:db,APP_ORIGIN:origin,REGISTRATION_ENABLED:'false',RUNTIME_ENABLED:'false'};const who={userId:alice.userId,sessionHash:'test',csrfHash:'test'};const planner={plan:async(_ctx:any,feedback:any)=>{expect(JSON.parse(feedback.error).text).toContain('JavaScript syntax: app.js');return [{path:'app.js',operation:'MODIFY',previousDigest:c.files.find((x:any)=>x.path==='app.js').digest,content:'const x = 1;',to:null,reason:'Correct observed syntax error; test planner output',risk:'low'}]}};const result=await repairApi(new Request(origin+'/api/projects/'+item.id+'/repair/'+session.id+'/propose',{method:'POST'}),env,who,planner);expect(result!.status).toBe(201);const patch:any=await result!.json();expect(patch.applied).toBe(false);expect((await db.prepare('SELECT revision FROM projects WHERE id=?').bind(item.id).first<any>())!.revision).toBe(1);expect((await request('/api/projects/'+item.id+'/repair/'+session.id+'/reviewed','POST',{},alice)).status).toBe(409);expect((await request('/api/proposals/'+patch.id+'/approve','POST',{digest:patch.digest},alice)).status).toBe(409);expect((await request('/api/proposals/'+patch.id+'/approve','POST',{digest:patch.digest,patchDigest:patch.patchDigest},alice)).status).toBe(200);expect((await request('/api/projects/'+item.id+'/repair/'+session.id+'/reviewed','POST',{},alice)).status).toBe(200);expect((await request('/api/projects/'+item.id+'/repair/'+session.id+'/complete','POST',{buildId:b.id},alice)).status).toBe(409);const next:any=await (await request('/api/projects/'+item.id+'/agent/context','GET',undefined,alice)).json();const logs2:string[]=[];const success=await build(next.snapshot.files,x=>logs2.push(x));expect(success.status).toBe('succeeded');const b2:any=await (await request('/api/projects/'+item.id+'/build','POST',{command:'build static-web-v1',baseRevision:2,sourceDigest:next.snapshot.sourceDigest},alice)).json();await request('/api/projects/'+item.id+'/build/'+b2.id+'/events','POST',{runtimeId:b2.runtimeId,events:logs2.map((text,i)=>({seq:i+1,stream:'stdout',text}))},alice);await request('/api/projects/'+item.id+'/build/'+b2.id+'/finish','POST',{runtimeId:b2.runtimeId,status:success.status,exitCode:success.exitCode,durationMs:success.durationMs},alice);const done:any=await (await request('/api/projects/'+item.id+'/repair/'+session.id+'/complete','POST',{buildId:b2.id},alice)).json();expect(done.status).toBe('complete');expect(done.trust).toBe('browser-unverified');await expect(db.prepare("UPDATE repair_sessions SET status='ready' WHERE id=?").bind(session.id).run()).rejects.toThrow('repair_terminal_immutable');});
});
